# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_value = _coerce_value(env_key, value, config)
            _set_nested_key(config, env_key, env_value)
    return config

def _coerce_value(key, value, config):
    default_value = _get_nested_key(config, key)
    if isinstance(default_value, int):
        return int(value)
    elif isinstance(default_value, float):
        return float(value)
    elif isinstance(default_value, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default_value, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for key {key}')

def _set_nested_key(d, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        if k not in d:
            d[k] = {}
        d = d[k]
    d[keys[-1]] = value

def _get_nested_key(d, key):
    keys = key.split('.')
    for k in keys:
        if k not in d:
            raise ConfigError(f'Missing key {key}')
        d = d[k]
    return d

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    config = load_config({}, 'config.toml')
    assert config == {'key': 'toml_value'}

def test_env_variable():
    os.environ['APP__KEY'] = 'env_value'
    config = load_config({}, env_prefix='APP')
    assert config == {'key': 'env_value'}

def test_precedence():
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    os.environ['APP__KEY'] = 'env_value'
    config = load_config({'key': 'default_value'}, 'config.toml', env_prefix='APP')
    assert config == {'key': 'env_value'}

def test_coercion_int():
    os.environ['APP__KEY'] = '123'
    config = load_config({'key': 0}, env_prefix='APP')
    assert config == {'key': 123}

def test_coercion_float():
    os.environ['APP__KEY'] = '123.45'
    config = load_config({'key': 0.0}, env_prefix='APP')
    assert config == {'key': 123.45}

def test_coercion_bool():
    os.environ['APP__KEY'] = 'true'
    config = load_config({'key': False}, env_prefix='APP')
    assert config == {'key': True}

def test_missing_default():
    os.environ['APP__KEY'] = 'value'
    with pytest.raises(ConfigError, match='Missing key key'):
        load_config({}, env_prefix='APP')

def test_missing_toml():
    config = load_config({}, 'nonexistent.toml')
    assert config == {}

def test_missing_env():
    with pytest.raises(ConfigError, match='Missing key key'):
        load_config({'key': 'value'}, env_prefix='APP')
